import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/index.md","filePath":"user-guide/index.md","lastUpdated":1786468666000}'),i={name:"user-guide/index.md"};function o(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="user-manual" tabindex="-1">User Manual <a class="header-anchor" href="#user-manual" aria-label="Permalink to &quot;User Manual&quot;">​</a></h1><p>Lertaro is a fast, keyboard-first file search launcher for Windows. It indexes your local drives (NTFS and ReFS via their change journals, other file systems by watching them directly) and network shares in the background, then lets you jump to any file, folder, or application in a fraction of a second.</p><p>This manual covers everything a day-to-day user needs:</p><ul><li><strong><a href="./getting-started.html">Getting Started</a></strong> — installing Lertaro and understanding its three search windows (main, quick, inline).</li><li><strong><a href="./search-syntax.html">Search Syntax</a></strong> — fuzzy matching, exclude/exact/prefix/suffix operators, OR groups, drive targeting, path mode, and pinyin aliasing for Chinese filenames.</li><li><strong><a href="./hotkeys.html">Hotkeys</a></strong> — every configurable shortcut and hardcoded key, with default bindings.</li><li><strong><a href="./actions-and-preview.html">Actions Menu &amp; Preview</a></strong> — the right-click-style actions list and the QuickLook preview pane.</li><li><strong><a href="./space-analyzer.html">Space Analyzer</a></strong> — a fast, index-only treemap for understanding how indexed files and folders use space.</li><li><strong><a href="./instant-answers.html">Instant Answers &amp; Keyword Shortcuts</a></strong> — the calculator, environment variables, run-command shortcuts, and keyword-triggered plugins like Process Manager, Window Switcher, Browser Data, Settings Search, Web Search, and Translator.</li><li><strong><a href="./cli.html">Command-Line Search (lff)</a></strong> — the fzf-style CLI companion for searching from a terminal.</li><li><strong><a href="./uri-protocol.html">URI Protocol (lertaro://)</a></strong> — jumping straight into a search or a specific setting from a link, another app, or a script.</li><li><strong><a href="./file-manager-support.html">Supported File Managers</a></strong> — which file managers and file-picker dialogs Lertaro can dock into, trigger Quick Navigation from, or detect the current folder of.</li><li><strong><a href="./settings/">Settings Reference</a></strong> — every settings page, tab, and option, itemized.</li><li><strong><a href="./troubleshooting.html">Troubleshooting</a></strong> — common problems and how to fix them.</li><li><strong><a href="./donate.html">Donate</a></strong> — if Lertaro has been useful to you.</li></ul><p>If you&#39;re setting Lertaro up for the first time, start with <strong>Getting Started</strong>.</p>',5)])])}const u=t(i,[["render",o]]);export{f as __pageData,u as default};
